import { ethers } from 'ethers';
import JSBI from 'jsbi';
const MAX_DECIMALS = 4;
export function fromReadableAmount(amount, decimals) {
    // Convert the amount to a string with the full decimal representation
    const amountStr = amount.toFixed(decimals);
    // Remove the decimal point and convert to BigInt
    const atomicAmount = JSBI.BigInt(ethers.utils.parseUnits(amountStr, decimals).toString());
    return atomicAmount;
}
export function toReadableAmount(rawAmount, decimals) {
    return ethers.utils.formatUnits(rawAmount, decimals).slice(0, MAX_DECIMALS);
}
export function displayTrade(trade) {
    return `${trade.inputAmount.toExact()} ${trade.inputAmount.currency.symbol} for ${trade.outputAmount.toExact()} ${trade.outputAmount.currency.symbol}`;
}
